  'vehicle_reg_guide_title': 'வாகன பதிவு வழிகாட்டி',
  'vehicle_guide_instructions': '• ஆர்சியுடன் பொருந்தக்கூடிய அதிகாரப்பூர்வ பதிவுத் தட்டு மற்றும் சேஸ் / விஐஎன் எண்ணை உள்ளிடவும்.\n• அனுப்புதல் மற்றும் பயணிகள் கண்காணிப்புக்கு ஒதுக்கப்பட்ட முகப்பு டிப்போ மற்றும் போக்குவரத்து வழியைத் தேர்ந்தெடுக்கவும்.\n• இடது, வலது, பின்புறம் மற்றும் அவசர வெளியேறும் இடத்தில் நிறுவப்பட்ட விளம்பரக் காட்சித் திரைகளின் எண்ணிக்கையை உள்ளமைக்கவும்.\n• இயங்குதள ஆய்வில் தேர்ச்சி பெற சட்டப்பூர்வ இணக்க ஆவணங்களை (ஆர்சி, உடற்தகுதி, காப்பீடு) பதிவேற்றவும்.',
