  'locked_super_admin_only': 'பூட்டப்பட்டது (சூப்பர் அட்மின் அதிகாரம் மட்டும்)',
  'current_status_label': 'தற்போதைய நிலை: @status',
  'super_admin_only_badge': 'சூப்பர் அட்மின் மட்டும்',
  'mark_driver_contacted_checkbox': 'ஓட்டுநருடன் தொடர்பு கொள்ளப்பட்டது எனக் குறிக்கவும் (அழைப்பு நிறைவடைந்தது)',
  'driver_voice_contact_notes_label': 'ஓட்டுநர் குரல் தொடர்பு குறிப்புகள் & மதிப்பீடு',
  'driver_voice_contact_notes_hint': 'எ.கா. மாலை 6:15 மணிக்கு ஓட்டுநர் ரமேஷுடன் பேசப்பட்டது. ஓட்டுநர் பாதுகாப்பாக உள்ளார், உதவி அனுப்பப்பட்டது.',
  'notes_shift_helper_text': 'இங்கு உள்ளிடப்பட்ட குறிப்புகள் சேமித்தவுடன் நேரடியாக மேலே உள்ள ஓட்டுநர் மதிப்பீட்டுப் பகுதிக்கு நகரும்.',
  'vehicle_recovered_checkbox_label': 'வாகனம் மற்றும் தளம் மீட்கப்பட்டது / பாதை சீரானது (நேரம் பதிவானது)',
  'field_remarks_dispatch_label': 'களக் குறிப்புகள் & அனுப்புகை விவரங்கள்',
  'field_remarks_dispatch_hint': 'கள அவதானிப்புகள், காவல் துறை விவரங்கள் அல்லது சூப்பர் அட்மினுக்கான குறிப்புகளைச் சேர்க்கவும்...',
  'save_driver_voice_contact_notes': 'குரல் தொடர்பு மற்றும் குறிப்புகளைச் சேமிக்கவும்',
  'saving_notes': 'குறிப்புகள் சேமிக்கப்படுகின்றன...',
  'driver_auto_selected_msg': 'பேருந்து @bus-க்கு ஓட்டுநர் "@driver" தானாகத் தேர்ந்தெடுக்கப்பட்டார்',
  'bus_auto_selected_msg': 'ஓட்டுநர் @driver-க்கு பேருந்து "@bus" தானாகத் தேர்ந்தெடுக்கப்பட்டது',
  'gps_coords_locked_msg': 'ஜிபிஎஸ் ஆயத்தொலைவுகள் பூட்டப்பட்டன: (@lat, @lng)',
  'video_attached_success_msg': 'சம்பவ வீடியோ பதிவு வெற்றிகரமாக இணைக்கப்பட்டது.',
  'enter_desc_before_proceeding': 'தொடர்வதற்கு முன் சம்பவத்தின் விளக்கத்தை உள்ளிடவும்.',
  'driver_contact_notes_saved_msg': 'ஓட்டுநர் தொடர்பு அழைப்பு மற்றும் குறிப்புகள் வெற்றிகரமாகப் பதிவு செய்யப்பட்டன!',
  'super_admin_recovery_restricted': 'சம்பவ நிலையை மாற்றவோ இறுதி மீட்பு ஒப்புதல் அளிக்கவோ சூப்பர் நிர்வாகிகளுக்கு மட்டுமே அதிகாரம் உள்ளது.',
  'super_admin_status_restricted': 'சம்பவ நிலை மாற்றம் சூப்பர் அட்மின் அதிகாரத்திற்கு மட்டுமே கட்டுப்படுத்தப்பட்டுள்ளது.',

    'emergency_report_broadcasted_desc': 'கட்டுப்பாட்டு அறை அனுப்புநர்கள், ஒதுக்கப்பட்ட டிப்போ மேலாளர்கள் மற்றும் அவசர சேனல்களுக்கு அவசர அறிக்கை ஒளிபரப்பப்பட்டது.',

