  'view_campaign_details': 'பிரச்சார விவரங்களைக் காண்க',
  'vmovexa_dooh_engine': 'VMOVEXA DOOH இன்ஜின்',
  'advertiser_faq1_a': 'பிரச்சாரங்களுக்குச் சென்று "பிரச்சாரத்தை உருவாக்கு" என்பதைத் தட்டவும். அடிப்படை தகவலை உள்ளிடவும், உங்கள் 16:9 உள்ளடக்கத்தைப் பதிவேற்றவும், வாகனங்களைத் தேர்ந்தெடுக்கவும், அட்டவணை மற்றும் பட்ஜெட்டை உள்ளமைக்கவும் மற்றும் சரிபார்ப்புக்குச் சமர்ப்பிக்கவும்.',
  'advertiser_faq1_q': 'போக்குவரத்து விளம்பர பிரச்சாரத்தை எவ்வாறு உருவாக்கி தொடங்குவது?',
  'advertiser_faq2_a': 'நாங்கள் MP4 (H.264), JPG, PNG மற்றும் HTML5 ஜிப் தொகுப்புகளை ஆதரிக்கிறோம். நிலையான தெளிவுத்திறன் 1920×1080 (16:9 விகிதம்), வீடியோ விளம்பரங்களுக்கான அதிகபட்ச காலம் 30 வினாடிகள் மற்றும் கோப்பு அளவு 50 MB க்கும் குறைவாக இருக்க வேண்டும்.',
  'advertiser_faq2_q': 'பரிந்துரைக்கப்பட்ட விவரக்குறிப்புகள் யாவை?',
  'advertiser_faq3_a': 'ஒவ்வொரு பிரச்சாரமும் கண்காணிக்கக்கூடிய QR அடையாளத்தை உருவாக்குகிறது. திரையில் காட்டப்படும் QR குறியீட்டை பயணிகள் ஸ்கேன் செய்யும் போது, கணினி நேரம், இருப்பிடம், வாகன ஐடியைப் பதிவு செய்து, அவர்களை உங்கள் இலக்குப் பக்கத்திற்கு திருப்பி விடுகிறது.',
  'advertiser_faq3_q': 'ஸ்மார்ட் QR குறியீடு லீட் பண்புக்கூறு எவ்வாறு செயல்படுகிறது?',
  'advertiser_faq4_a': 'பிரச்சாரங்களுக்கு தினசரி அல்லது மொத்த பட்ஜெட் அடிப்படையில் கட்டணம் வசூலிக்கப்படுகிறது. விளம்பரச் செலவில் ஜிஎஸ்டி (18%) கணக்கிடப்படுகிறது. ஒப்புதலுக்குப் பிறகு வரி வரவுகளுடன் கூடிய இன்வாய்ஸ்கள் தானாகவே உருவாக்கப்படும்.',
  'advertiser_faq4_q': 'பில்லிங், ஜிஎஸ்டி இன்வாய்ஸ்கள் மற்றும் பிடித்தங்கள் எவ்வாறு செயல்படுகின்றன?',
