  'gov_help.faqs_title': 'அடிக்கடி கேட்கப்படும் கேள்விகள்',
  'gov_help.faqs_search_ph': 'அடிக்கடி கேட்கப்படும் கேள்விகளைத் தேடுங்கள்...',
  'gov_help.faq1_q': 'அனைத்து நகரப் போக்குவரத்து காட்சிகளிலும் அவசரகால பொது அறிவிப்பை எவ்வாறு செயல்படுத்துவது?',
  'gov_help.faq1_a': 'ஒளிபரப்பு அறிவிப்புகளுக்குச் சென்று, "அவசர எச்சரிக்கை" என்பதைத் தேர்ந்தெடுத்து, புவியியல் மண்டலங்கள் அல்லது வழித்தடங்களை வரையறுத்து, எச்சரிக்கை கால அளவை அமைத்து, உங்கள் இரு காரணி அங்கீகார பின் மூலம் உறுதிப்படுத்தவும்.',
  'gov_help.faq2_q': 'பயணிகள் அடர்த்தி டெலிமெட்ரி எவ்வளவு அடிக்கடி புதுப்பிக்கப்படுகிறது?',
  'gov_help.faq2_a': 'அனைத்து நகராட்சி வழித்தடங்களிலும் ஜிபிஎஸ், ஸ்மார்ட் டிக்கெட்டிங் மற்றும் நிறுத்த கேமரா சென்சார்களிலிருந்து ஒவ்வொரு 60 வினாடிகளுக்கும் பயணிகள் சுமை டெலிமெட்ரி திரட்டப்படுகிறது.',
  'gov_help.faq3_q': 'மாநில தணிக்கைகளுக்கான சட்டரீதியான இணக்கப் பதிவுகளை எவ்வாறு ஏற்றுமதி செய்வது?',
  'gov_help.faq3_a': 'இணக்க அறிக்கைகளுக்குச் சென்று, தணிக்கைத் தேதி வரம்பைத் தேர்ந்தெடுத்து, மாற்ற முடியாத SHA-256 கையொப்பமிடப்பட்ட CSV அல்லது PDF தணிக்கைத் தொகுப்புகளை ஏற்றுமதி செய்யவும்.',
  'gov_help.faq4_q': 'வணிக விளம்பரக் காட்சிகளுக்குத் தேவையான பாதுகாப்புத் தரநிலைகள் யாவை?',
  'gov_help.faq4_a': 'அனைத்து போக்குவரத்து காட்சிகளும் இரவு நேர போக்குவரத்தின் போது கட்டாய தானியங்கி மங்கல் அம்சத்துடன் வாகன அதிர்வு (ISO 16750) மற்றும் தீ தடுப்பு பாதுகாப்பு தரநிலைகளைக் கடைப்பிடிக்கின்றன.',
  'gov_help.raise_ticket_title': 'ஆதரவு டிக்கெட் பதிவு செய்',
