  'finance_help.faq1_q': 'தினசரி விளம்பரதாரர் பில்லிங் கழிவுகள் எப்போது செயல்படுத்தப்படுகின்றன?',
  'finance_help.faq1_a': 'சரிபார்க்கப்பட்ட பதிவுகளின் அடிப்படையில் 23:59:59 IST மணிக்கு விளம்பரதாரர் வாலெட்டிலிருந்து தினசரி விளம்பரச் செலவு தீர்க்கப்படுகிறது.',
