  'finance_help.faq2_a': 'போக்குவரத்து டிஜிட்டல் விளம்பரம் 18% ஜிஎஸ்டியில் SAC 998363 இன் கீழ் வகைப்படுத்தப்பட்டுள்ளது.',
  'finance_help.faq3_q': 'வங்கி சமரச முரண்பாடுகளை எவ்வாறு தீர்ப்பது?',
  'finance_help.faq3_a': 'நிதி சமரசத்தில் மாதாந்திர வங்கி அறிக்கை CSV ஐ பதிவேற்றவும். எஞ்சின் தானாகவே UTR எண்களைப் பொருத்துகிறது.',
  'finance_help.faq4_q': 'திரை செயலிழப்பு கிரெடிட் நோட்டுகளை வழங்குவதற்கான நடைமுறை என்ன?',
  'finance_help.faq4_a': 'விளம்பரதாரர் SLA தகராறைத் தாக்கல் செய்யும் போது, நிதி அதிகாரிகள் நேரடியாக வாலெட்டுக்கு கிரெடிட் நோட்டை வழங்கலாம்.',
